using System.Security.Cryptography; using CubeAntivirus.Models; namespace CubeAntivirus.Core; public sealed class FileScanner { private static readonly HashSet<string> Extensions = new(StringComparer.OrdinalIgnoreCase) { ".txt", ".bat", ".cmd", ".ps1", ".vbs", ".js", ".py" }; private static readonly string[] Indicators = { "malicious_trojan_downloader_script", "powershell.exe -nop -w hidden", "Invoke-Expression", "FromBase64String" }; private readonly HashDatabase _db; private readonly SemaphoreSlim _gate = new(Math.Max(2, Environment.ProcessorCount)); public FileScanner(HashDatabase db) => _db = db; public async Task<ScanResult> ScanFileAsync(string path, CancellationToken token = default) { await _gate.WaitAsync(token); try { await using var stream = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.Read, 81920, FileOptions.Asynchronous | FileOptions.SequentialScan); var hash = Convert.ToHexString(await SHA256.HashDataAsync(stream, token)); if (_db.Contains(hash)) return new(path, ScanStatus.Threat, "SHA-256 signature match", hash); if (Extensions.Contains(Path.GetExtension(path)) && new FileInfo(path).Length <= 2_000_000) { var text = await File.ReadAllTextAsync(path, token); var hit = Indicators.FirstOrDefault(x => text.Contains(x, StringComparison.OrdinalIgnoreCase)); if (hit != null) return new(path, ScanStatus.Warning, "Heuristic indicator: " + hit, hash); } return new(path, ScanStatus.Clean, "No known indicators", hash); } catch (OperationCanceledException) { throw; } catch (Exception ex) when (ex is IOException or UnauthorizedAccessException) { return new(path, ScanStatus.Error, ex.Message); } finally { _gate.Release(); } } public async IAsyncEnumerable<ScanResult> ScanDirectoryAsync(string root, [System.Runtime.CompilerServices.EnumeratorCancellation] CancellationToken token = default) { foreach (var file in Enumerate(root)) { token.ThrowIfCancellationRequested(); yield return await ScanFileAsync(file, token); } } private static IEnumerable<string> Enumerate(string root) { var dirs = new Stack<string>(); dirs.Push(root); while (dirs.Count > 0) { var dir = dirs.Pop(); IEnumerable<string> files; try { files = Directory.EnumerateFiles(dir); } catch (Exception ex) when (ex is IOException or UnauthorizedAccessException) { continue; } foreach (var file in files) yield return file; IEnumerable<string> children; try { children = Directory.EnumerateDirectories(dir); } catch (Exception ex) when (ex is IOException or UnauthorizedAccessException) { continue; } foreach (var child in children) { try { if ((File.GetAttributes(child) & FileAttributes.ReparsePoint) == 0) dirs.Push(child); } catch (Exception ex) when (ex is IOException or UnauthorizedAccessException) { } } } } }